"""Knight's Tour — backtracking with Warnsdorff's heuristic.

Plain backtracking stalls even on an 8x8 board. Warnsdorff's rule — always move
to the square with the fewest onward moves — finds a tour almost immediately,
and the backtracking stays in place as a safety net when the heuristic ties.

Time: near-linear in practice   Space: O(n^2)
"""
from typing import List

MOVES = ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2))


class Solution:
    def knightTour(self, n: int) -> List[List[int]]:
        board = [[-1] * n for _ in range(n)]
        board[0][0] = 0

        def onward_moves(r: int, c: int) -> int:
            return sum(1 for dr, dc in MOVES
                       if 0 <= r + dr < n and 0 <= c + dc < n and board[r + dr][c + dc] == -1)

        def solve(r: int, c: int, step: int) -> bool:
            if step == n * n:
                return True
            candidates = []
            for dr, dc in MOVES:
                x, y = r + dr, c + dc
                if 0 <= x < n and 0 <= y < n and board[x][y] == -1:
                    candidates.append((onward_moves(x, y), x, y))
            candidates.sort()                    # Warnsdorff: fewest exits first
            for _, x, y in candidates:
                board[x][y] = step
                if solve(x, y, step + 1):
                    return True
                board[x][y] = -1
            return False

        return board if solve(0, 0, 1) else []
